from .ta5g_tshark_filters import ta5g_tshark_filters
from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn
from robot.errors import ExecutionFailed
from datetime import datetime
from ta5g_global_var import TSHARK_SUBDIR, DEFAULT_TCP_PCAP
from ta5g_interface_tools import ta5g_interface_tools
from os import path
import time


class TsharkVerify(object):
    def verify_tshark(
        self, alias, packet_filter, pass_criteria, source_ip='0.0.0.0/0', pcap_file_path=None, timeout=16, continue_on_failure=True, subcase=None
    ):
        """
        :param alias:
        :param packet_filter:
        :param pass_criteria:
        :param source_ip:
        :param pcap_file_path:
        :param timeout
        :param continue_on_failure:
        :return:
        """

        if pcap_file_path == 'default':
            pcap_file_path = self._set_default_file_path(pcap_file_path=pcap_file_path)
        elif pcap_file_path == 'subcase' and subcase:
            pcap_file_path = self._set_file_path_for_subcase(subcase=subcase)
        t1 = datetime.now()
        num_of_messages = 'Did not get any packets'
        while (datetime.now() - t1).seconds <= int(timeout):
            num_of_messages = self.get_packets_count_for_tshark(
                packet_filter=packet_filter, source_ip=source_ip, alias=alias, pcap_file_path=pcap_file_path
            )
            result = eval("{}{}".format(num_of_messages, pass_criteria))
            if result:
                return True
            else:
                time.sleep(3)
        logger.trace(
            "Packet filter: {}\n\n" "Captured {}{} Expected".format(packet_filter, num_of_messages, pass_criteria)
        )
        raise ExecutionFailed(
            message="{}{}  Should be true".format(num_of_messages, pass_criteria), continue_on_failure=continue_on_failure
        )

    def verify_tshark_for_single_message(
        self, alias, packet_filter, source_ip='0.0.0.0/0', pcap_file_path=None, timeout=16
    ):
        """
        :param alias:
        :param packet_filter:
        :param source_ip:
        :param pcap_file_path:
        :param timeout:
        :return:
        """
        self.verify_tshark(
            alias=alias,
            packet_filter=packet_filter,
            pass_criteria='==1',
            source_ip=source_ip,
            pcap_file_path=pcap_file_path,
            timeout=timeout,
        )

    def multiple_ue_verify_tshark_for_given_number_of_messages(
        self, alias, packet_filter, number_of_messages, ue_id_list, source_ip='0.0.0.0/0'
    ):
        """
        :param alias:
        :param packet_filter:
        :param number_of_messages:
        :param ue_id_list:
        :param source_ip:
        :return:
        """
        for ue_id in ue_id_list:
            self.verify_tshark(
                alias=alias,
                packet_filter='iphy.ue_id=={}&&{}'.format(ue_id, packet_filter),
                pass_criteria=' =={}'.format(number_of_messages),
                source_ip=source_ip,
            )

    def verify_tshark_for_given_number_of_messages(
        self, alias, packet_filter, number_of_messages, source_ip='0.0.0.0/0', timeout=16
    ):
        """
        :param alias:
        :param packet_filter:
        :param number_of_messages:
        :param source_ip:
        :param timeout:
        :return:
        """
        self.verify_tshark(
            alias=alias,
            packet_filter=packet_filter,
            pass_criteria=' =={}'.format(number_of_messages),
            source_ip=source_ip,
            timeout=timeout,
        )

    def multiple_ue_verify_tshark_for_no_messages(self, alias, packet_filter, ue_id_list, source_ip='0.0.0.0/0'):
        """
        :param alias:
        :param packet_filter:
        :param ue_id_list:
        :param source_ip:
        :return:
        """
        for ue_id in ue_id_list:
            self.verify_tshark(
                alias=alias,
                packet_filter='iphy.ue_id=={}&&{}'.format(ue_id, packet_filter),
                pass_criteria=' ==0',
                source_ip=source_ip,
            )

    def verify_tshark_for_no_messages(
        self, alias, packet_filter, source_ip='0.0.0.0/0', pcap_file_path='default', timeout=16
    ):
        """
        :param timeout:
        :param alias:
        :param packet_filter:
        :param source_ip:
        :param pcap_file_path:
        :return:
        """
        self.verify_tshark(
            alias=alias,
            packet_filter=packet_filter,
            pass_criteria='==0',
            source_ip=source_ip,
            pcap_file_path=pcap_file_path,
            timeout=timeout,
        )

    def multiple_ue_verify_tshark_for_at_least_given_number_of_messages(
        self, alias, packet_filter, number_of_messages, ue_id_list, source_ip='0.0.0.0/0'
    ):
        """
        :param alias:
        :param packet_filter:
        :param number_of_messages:
        :param ue_id_list:
        :param source_ip:
        :return:
        """
        for ue_id in ue_id_list:
            self.verify_tshark(
                alias=alias,
                packet_filter='iphy.ue_id=={}&&{}'.format(ue_id, packet_filter),
                pass_criteria=' >={}'.format(number_of_messages),
                source_ip=source_ip,
            )

    def verify_tshark_for_at_least_given_number_of_messages(
        self, alias, packet_filter, number_of_messages, source_ip='0.0.0.0/0', timeout=16
    ):
        """
        :param alias:
        :param packet_filter:
        :param number_of_messages:
        :param source_ip:
        :param timeout:
        :return:
        """
        self.verify_tshark(
            alias=alias,
            packet_filter=packet_filter,
            pass_criteria=' >={}'.format(number_of_messages),
            source_ip=source_ip,
            timeout=timeout,
        )

    def verify_tshark_for_not_more_than_given_number_of_messages(
        self, alias, packet_filter, number_of_messages, source_ip='0.0.0.0/0', timeout=16
    ):
        """
        :param alias:
        :param packet_filter:
        :param number_of_messages:
        :param source_ip:
        :param timeout:
        :return:
        """
        self.verify_tshark(
            alias=alias,
            packet_filter=packet_filter,
            pass_criteria=' <={}'.format(number_of_messages),
            source_ip=source_ip,
            timeout=timeout,
        )

    def verify_tshark_for_attach_on_nas_eps(self, alias, number_of_attaches, source_ip='0.0.0.0/0'):
        """
        :param alias:
        :param number_of_attaches:
        :param source_ip:
        :return:
        """
        s1_ue_attach_complete = ta5g_tshark_filters().S1_UE_ATTACH_COMPLETE
        self.verify_tshark_for_given_number_of_messages(
            alias=alias,
            number_of_messages=number_of_attaches,
            packet_filter='{} && ip.src == {}'.format(s1_ue_attach_complete, source_ip),
        )

    def verify_tshark_for_detach_on_s1ap(self, alias, number_of_attaches, source_ip='0.0.0.0/0'):
        """
        :param alias:
        :param number_of_attaches:
        :param source_ip:
        :return:
        """
        s1ap_detach_complete = ta5g_tshark_filters().S1AP_DETACH_COMPLETE
        self.verify_tshark_for_given_number_of_messages(
            alias=alias,
            number_of_messages=number_of_attaches,
            packet_filter='{} && ip.src == {}'.format(s1ap_detach_complete, source_ip),
        )

    def verify_tshark_for_ngap_ue_context_release(self, alias, ran_id, amf_id):
        """
        Verifies tshark messages for ue context release for ran_id=ue_number-1
        :param amf_id:
        :param alias:
        :param ran_id:
        :return:
        """
        ngap_context_release_complete = ta5g_tshark_filters().NGAP_UE_CONTEXT_RELEASE_COMPLETE
        ngap_ue_amf_id = ta5g_tshark_filters().NGAP_UE_AMF_ID
        ngap_ue_ran_id = ta5g_tshark_filters().NGAP_UE_RAN_ID
        self.verify_tshark_for_single_message(
            alias=alias,
            packet_filter="{} == {} && {}".format(ngap_ue_ran_id, ran_id, ngap_context_release_complete)
        )
        self.verify_tshark_for_single_message(
            alias=alias,
            packet_filter="{} == {} && {}".format(ngap_ue_amf_id, amf_id, ngap_context_release_complete)
        )

    @staticmethod
    def get_packets_count_for_tshark(packet_filter, source_ip, alias, pcap_file_path):
        num_of_messages = (
            BuiltIn()
            .get_library_instance('ute_tshark')
            .get_packets_count(
                packet_filter="{} && (ip.src == {} || ipv6.src==::/0)".format(packet_filter, source_ip),
                alias=alias,
                pcap_file_path=pcap_file_path,
            )
        )
        return num_of_messages

    def _set_default_file_path(self, pcap_file_path):
        output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        test_name = ta5g_interface_tools().get_robot_test_name()
        test_name_dir_exists = path.isdir(path.join(output_dirpath, test_name))
        tshark_test_name_path = path.join(output_dirpath, test_name, TSHARK_SUBDIR, DEFAULT_TCP_PCAP)
        tshark_output_dir_path = path.join(output_dirpath, TSHARK_SUBDIR, DEFAULT_TCP_PCAP)
        if test_name_dir_exists:
            pcap_file_path = tshark_test_name_path
        else:
            pcap_file_path = tshark_output_dir_path
        return pcap_file_path

    def _set_file_path_for_subcase(self, subcase):
        output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        test_name = ta5g_interface_tools().get_robot_test_name()
        test_name_dir_exists = path.isdir(path.join(output_dirpath, test_name))
        tshark_test_name_path = path.join(output_dirpath, test_name, TSHARK_SUBDIR, (subcase + "_" + DEFAULT_TCP_PCAP))
        tshark_output_dir_path = path.join(output_dirpath, TSHARK_SUBDIR, (subcase + "_" + DEFAULT_TCP_PCAP))
        if test_name_dir_exists:
            pcap_file_path = tshark_test_name_path
        else:
            pcap_file_path = tshark_output_dir_path
        return pcap_file_path

    def verify_tshark_for_given_list_of_messages(
            self, alias, packet_filter_list, source_ip='0.0.0.0/0', pcap_file_path='default', pass_criteria='==1', timeout=16
    ):
        """
        :param alias:
        :param packet_filter_list:
        :param source_ip:
        :param pcap_file_path:
        :param pass_criteria:
        :param timeout:
        :return:
        """
        for packet_filter in packet_filter_list:
            self.verify_tshark(
                alias=alias,
                packet_filter=packet_filter,
                pass_criteria=pass_criteria,
                source_ip=source_ip,
                pcap_file_path=pcap_file_path,
                timeout=timeout,
            )
